non-blocking-algorithm.pseudocode:
class LockFreeStack:  # Treiber 스택
    def __init__(self):
        self.top = AtomicRef(None)

    def push(self, value):
        node = Node(value)
        while True:
            old = self.top.load()
            node.next = old
            # 그 사이 top이 안 바뀌었을 때만 교체
            if self.top.cas(old, node):
                return

    def pop(self):
        while True:
            old = self.top.load()
            if old is None:
                return None
            # ABA 방지: 태그 포인터·해저드 포인터 필요
            if self.top.cas(old, old.next):
                return old.value
            # 실패 → 다른 스레드가 진행한 것 → 재시도

