def nru_victim(pages):
    classes = [[], [], [], []]
    for p in pages:  # 등급 = 2*R + M
        classes[2 * p.ref + p.mod].append(p)
    for c in classes:  # 낮은 등급부터
        if c:
            return random_choice(c)  # 같은 등급 내 임의

def on_timer_tick(pages):
    for p in pages:
        p.ref = 0  # 주기적으로 참조 비트 초기화
